using System;namespace Recovered.Gameplay {public static class PtlSubmitMatrices {public static void CopyCamera(SoundSetupImage m,uint destination){for(uint i=0;i<30;i++)m.Word(unchecked(destination+i*4),m.Word(0x9736e8+i*4));}public static uint[] CameraValues(SoundSetupImage m){uint[] words=new uint[30];for(uint i=0;i<30;i++)words[i]=m.Word(0x9736e8+i*4);return words;}static uint Spill(uint bits,bool negate){if((bits&0x7fffffff)>0x7f800000)bits|=0x400000;return negate?bits^0x80000000:bits;}public static void BasisModifier(SoundSetupImage m,uint destination){for(uint row=0;row<3;row++){uint source=0x80b708+row*16;m.Word(unchecked(destination+row*4),Spill(m.Word(source),true));m.Word(unchecked(destination+16+row*4),Spill(m.Word(source+4),false));m.Word(unchecked(destination+32+row*4),Spill(m.Word(source+8),true));}m.Word(unchecked(destination+0x2c),0);m.Word(unchecked(destination+0x1c),0);m.Word(unchecked(destination+0x0c),0);m.Word(unchecked(destination+0x3c),0x3f800000);}}}
